if (params.flip) u = 1 - u;
const ar = width/height;
let px = u*ar, py = v;
const s = params.seed;
const w1 = noise(px*params.scale + s, py*params.scale + 1.7) + 0.5*noise(px*params.scale*2.1 + 3.1, py*params.scale*2.1 - s);
const w2 = noise(px*params.scale + 5.2, py*params.scale + 9.1 + s) + 0.5*noise(px*params.scale*2.1 - 2.3, py*params.scale*2.1 + 4.4);
px += (w1/1.5-0.5)*params.warp; py += (w2/1.5-0.5)*params.warp;
const P = [[0.02*ar,0.02,0.024,0.059,0.2,0.36],[0.10*ar,0.95,0.027,0.078,0.216,0.30],[0.55*ar,0.20,0.071,0.141,0.541,0.30],[0.95*ar,0.08,0.184,0.314,0.894,0.20],[0.70*ar,0.65,0.102,0.2,0.722,0.25],[0.98*ar,0.95,0.082,0.149,0.604,0.25],[0.85*ar,0.40,0.212,0.329,0.878,0.09]];
let r=0,g=0,b=0,ws=0;
for (let i=0;i<7;i++){ const q=P[i]; const dx=px-q[0], dy=py-q[1]; const w=Math.exp(-(dx*dx+dy*dy)/q[5]); r+=q[2]*w; g+=q[3]*w; b+=q[4]*w; ws+=w; }
r/=ws; g/=ws; b/=ws;
const f = noise(px*1.1 + 3.3, py*1.1 - s);
const band = Math.sin((px*1.4 + py*2.0 + f*2.6) * params.freq);
const soft = smoothstep(0.2, 1.0, band);
const hl = soft*soft * params.sheen * smoothstep(0.25, 1.0, u);
r += (0.278-r)*hl; g += (0.392-g)*hl; b += (0.894-b)*hl;
const gl = smoothstep(0.92, 1.0, band); const glint = gl*gl*gl * params.glint * smoothstep(0.35, 1.0, u);
r += (0.592-r)*glint; g += (0.659-g)*glint; b += (0.949-b)*glint;
const n = (hash(x, y) - 0.5) * params.grain;
return [clamp(r+n,0,1), clamp(g+n,0,1), clamp(b+n,0,1)];
